import os, json, numpy as np, sys
N = 26
sys.path.append('storage/noesis/nmap')

def run_scan():
    try:
        import scan_nudged as SN
        return SN.scan_inquire_nudged()
    except Exception as e:
        os.makedirs('storage/noesis/nmap/nudged', exist_ok=True)
        with open('storage/noesis/nmap/nudged/scan_error.txt','w',encoding='utf-8') as f:
            f.write(str(e))
        return []

def load_pack():
    try:
        c = np.loadtxt('storage/noesis/exports/sota_243/centers.txt')
        r = np.loadtxt('storage/noesis/exports/sota_243/radii.txt')
        c = np.array(c, dtype=float).reshape(N, 2)
        r = np.array(r, dtype=float).reshape(N,)
        return c, r
    except Exception:
        coords = [0.1,0.3,0.5,0.7,0.9]
        centers = [[x,y] for x in coords for y in coords][:25] + [[0.2,0.2]]
        radii = [0.09999]*25 + [0.0414213]
        return np.array(centers, dtype=float), np.array(radii, dtype=float)

def construct_packing():
    results = run_scan()
    try:
        os.makedirs('storage/noesis/nmap/nudged', exist_ok=True)
        with open('storage/noesis/nmap/nudged/last_scan.json','w',encoding='utf-8') as f:
            json.dump({"count": len(results), "items": results}, f, indent=2)
    except Exception:
        pass
    return load_pack()
